def oranges_rotting(grid):
    R, C = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    q = deque()
    fresh = 0
    for i in range(R):
        for j in range(C):
            if g[i][j] == 2:
                q.append((i, j))
            elif g[i][j] == 1:
                fresh += 1
    minutes = 0
    while q and fresh:
        for _ in range(len(q)):
            i, j = q.popleft()
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = i + di, j + dj
                if 0 <= a < R and 0 <= b < C and g[a][b] == 1:
                    g[a][b] = 2
                    fresh -= 1
