    for (let j = 0; j < C; j++) {
      if (g[i][j] === 2) q.push([i, j]);
      else if (g[i][j] === 1) fresh++;
    }
  }
  let minutes = 0;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
