function jobScheduling(startTime, endTime, profit) {
  const idx = startTime.map((_, i) => i).sort((a, b) => endTime[a] - endTime[b]);
  const ends = [];
  const dp = [0];
  for (const k of idx) {
    const s = startTime[k];
