        for _ in range(len(q)):
            r, c, rem = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = r + dr, c + dc
                if 0 <= a < R and 0 <= b < C:
                    nr = rem - grid[a][b]
                    if nr < 0:
